public class BankAccount {
    private BigDecimal balance = BigDecimal.ZERO;   // state

    public void deposit(BigDecimal amount) {        // behavior
        balance = balance.add(amount);
    }

    public void withdraw(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("Insufficient funds");
        balance = balance.subtract(amount);         // the rule lives here, once
    }
}

