public interface Shape { double area(); }                 // abstraction

public class Circle implements Shape {
    private final double radius;                           // encapsulation
    public Circle(double radius) { this.radius = radius; }
    public double area() { return Math.PI * radius * radius; }
}

public class Rectangle implements Shape {
    protected final double width, height;
    public Rectangle(double width, double height) { this.width = width; this.height = height; }
    public double area() { return width * height; }
}

public class Square extends Rectangle {                    // inheritance (safe: Rectangle has no setters — see LSP in SOLID)
    public Square(double side) { super(side, side); }
}

List<Shape> shapes = List.of(new Circle(1), new Square(2));
double total = shapes.stream().mapToDouble(Shape::area).sum();   // polymorphism

// WRONG: every new shape edits this method
double area(Object shape) {
    if (shape instanceof Circle c) return Math.PI * c.radius() * c.radius();
    if (shape instanceof Square s) return s.side() * s.side();
    throw new IllegalArgumentException("Unknown shape");
}

// RIGHT: each shape knows its own area
double total = shapes.stream().mapToDouble(Shape::area).sum();

public class Order {
