public interface Channel { void send(String to, String message); }

public class Notifier {
    private final Channel channel;          // has a channel
    private final int attempts;

    public Notifier(Channel channel, int attempts) {
        this.channel = channel;
        this.attempts = attempts;
    }

    public void notify(String to, String message) {
        for (int i = 1; i <= attempts; i++) {
            try { channel.send(to, message); return; }
            catch (RuntimeException e) { if (i == attempts) throw e; }
        }
    }
}

new Notifier(new EmailChannel(), 3);    // email with retry
new Notifier(new SmsChannel(), 1);      // SMS without retry — no new class

