public record Money(BigDecimal amount, String currency) {
    public Money {                                       // compact constructor: validation
        if (amount.signum() < 0) throw new IllegalArgumentException("Negative amount");
        Objects.requireNonNull(currency);
    }
    public Money plus(Money other) {                     // "changing" returns a new object
        if (!currency.equals(other.currency)) throw new IllegalArgumentException("Different currencies");
        return new Money(amount.add(other.amount), currency);
    }
}

Money price = new Money(new BigDecimal("10.00"), "BRL");
price.amount();                                          // accessor: amount(), not getAmount()
Money total = price.plus(price);                         // price is unchanged

