interface ShippingCost {
    BigDecimal calculate(BigDecimal weight);
}

class ExpressShipping implements ShippingCost {
    public BigDecimal calculate(BigDecimal weight) { return weight.multiply(new BigDecimal("12.50")); }
}

class StandardShipping implements ShippingCost {
    public BigDecimal calculate(BigDecimal weight) { return weight.multiply(new BigDecimal("7.90")); }
}

class Checkout {
    private final ShippingCost shipping;
    Checkout(ShippingCost shipping) { this.shipping = shipping; }

    BigDecimal total(BigDecimal subtotal, BigDecimal weight) {
        return subtotal.add(shipping.calculate(weight));
    }
}

