    if (carrier.equals("EXPRESS")) return weight.multiply(new BigDecimal("12.50"));
    else if (carrier.equals("STANDARD")) return weight.multiply(new BigDecimal("7.90"));
    else throw new IllegalArgumentException(carrier);
}

// RIGHT: a new carrier is a new ShippingCost implementation; Checkout does not change

